-- Migration 433: trailer hitch kit builder (Craig 2026-10-25)
--
-- Hitch kits are built on the estimate, not set up ahead of time: pick the
-- vehicle and year, then a hitch, a 4-way wiring harness, an optional 7/4-way
-- adapter and a brake controller (good / better / best / Bluetooth). The
-- choices land as one kit group of ordinary lines (same kit_group_id columns
-- as rack kits, migration 332), each line carrying its own install labor.
--
--   hitch_parts     every part the builder can offer, with Curt's photo,
--                   specs, feature bullets and fitment notes
--   hitch_fitment   which vehicle (vehicle_platforms.key) and model years
--                   each vehicle-specific part fits; adapters and brake
--                   controllers fit everything and have no rows here
--   hitch_settings  labor hours per step (one row)
--
-- Data: CURT's public catalog (curtmfg.com, same parts etrailer sells as
-- "C" + the Curt number) for every FleetSuite vehicle, 2019-2026, pulled
-- 2026-10-24. list_price is Curt's list price; an estimate uses the NetSuite
-- item's price when the part exists there.

CREATE TABLE IF NOT EXISTS hitch_parts (
  sku TEXT PRIMARY KEY,
  -- hitch | wiring | adapter | factory_adapter | brake_controller | brake_harness
  role TEXT NOT NULL,
  name TEXT NOT NULL,
  list_price NUMERIC,
  hitch_class TEXT,
  receiver TEXT,
  specs JSONB NOT NULL DEFAULT '{}'::jsonb,
  features JSONB NOT NULL DEFAULT '[]'::jsonb,
  notes JSONB NOT NULL DEFAULT '[]'::jsonb,
  image_url TEXT,
  -- Only works on a vehicle with factory trailer wiring (USCAR tow plug).
  needs_factory_wiring BOOLEAN NOT NULL DEFAULT false,
  -- Brake controllers: good | better | best | bluetooth.
  tier TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  active BOOLEAN NOT NULL DEFAULT true,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS hitch_fitment (
  id BIGSERIAL PRIMARY KEY,
  platform_key TEXT NOT NULL,
  sku TEXT NOT NULL REFERENCES hitch_parts(sku) ON DELETE CASCADE,
  year_start INTEGER NOT NULL,
  year_end INTEGER NOT NULL,
  UNIQUE (platform_key, sku)
);
CREATE INDEX IF NOT EXISTS idx_hitch_fitment_platform ON hitch_fitment (platform_key);

CREATE TABLE IF NOT EXISTS hitch_settings (
  id INTEGER PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  labor_hitch NUMERIC NOT NULL DEFAULT 1,
  labor_wiring NUMERIC NOT NULL DEFAULT 1,
  labor_adapter NUMERIC NOT NULL DEFAULT 0.75,
  labor_brake NUMERIC NOT NULL DEFAULT 1,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE hitch_parts ENABLE ROW LEVEL SECURITY;
ALTER TABLE hitch_fitment ENABLE ROW LEVEL SECURITY;
ALTER TABLE hitch_settings ENABLE ROW LEVEL SECURITY;

-- Same posture as part_kits: any signed-in user reads, internal staff manage.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Authenticated users can read hitch parts' AND tablename = 'hitch_parts') THEN
    CREATE POLICY "Authenticated users can read hitch parts" ON hitch_parts FOR SELECT TO authenticated USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Internal staff can manage hitch parts' AND tablename = 'hitch_parts') THEN
    CREATE POLICY "Internal staff can manage hitch parts" ON hitch_parts FOR ALL TO authenticated
      USING (public.is_internal_staff()) WITH CHECK (public.is_internal_staff());
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Authenticated users can read hitch fitment' AND tablename = 'hitch_fitment') THEN
    CREATE POLICY "Authenticated users can read hitch fitment" ON hitch_fitment FOR SELECT TO authenticated USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Internal staff can manage hitch fitment' AND tablename = 'hitch_fitment') THEN
    CREATE POLICY "Internal staff can manage hitch fitment" ON hitch_fitment FOR ALL TO authenticated
      USING (public.is_internal_staff()) WITH CHECK (public.is_internal_staff());
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Authenticated users can read hitch settings' AND tablename = 'hitch_settings') THEN
    CREATE POLICY "Authenticated users can read hitch settings" ON hitch_settings FOR SELECT TO authenticated USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'Internal staff can manage hitch settings' AND tablename = 'hitch_settings') THEN
    CREATE POLICY "Internal staff can manage hitch settings" ON hitch_settings FOR ALL TO authenticated
      USING (public.is_internal_staff()) WITH CHECK (public.is_internal_staff());
  END IF;
END $$;

-- ── Data ────────────────────────────────────────────────────────────────
-- Re-running keeps anything staff changed (active, tier, sort order).
ON CONFLICT (sku) DO NOTHING;

ON CONFLICT (platform_key, sku) DO NOTHING;
