  ('13264', 'hitch', 'Class 3 trailer hitch, 2" receiver, select toyota tacoma', 266.95, '3', '2"', '{"Gross trailer weight": "6,000 LB", "Tongue weight": "900 LB", "Weight distribution": "8,000 LB", "Receiver": "2 IN", "Finish": "Gloss Black Powder Coat", "Drilling required": "No"}', '["Rated to 6,000 lbs. gross trailer weight and 900 lbs. tongue weight", "Compatible with weight distribution hitch (8,000 lbs. WD / 900 lbs. WDTW)", "Engineered with a vehicle-specific design for a custom fit", "Concealed main body for OE look and seamless integration with the vehicle", "Tested for safety in accordance with SAE J684", "Precisely welded for superior strength and fit"]', '["Trailer hitch weight ratings are limited to vehicle manufacturer''s stated capacities", "Not compatible for use with vertical hanging bicycles (bike racks that require the bicycles to be hung / mounted vertically)", "Includes installation hardware"]', 'https://www.curtmfg.com/media/catalog/product/1/3/13264_1024x768_a.jpg', false, NULL, 0),
  ('13638', 'hitch', 'Class 3 trailer hitch, 2" receiver, select toyota tacoma', 272.95, '3', '2"', '{"Receiver": "2 IN", "Drilling required": "No"}', '["Rated to 7,000 lbs. gross trailer weight and 700 lbs. tongue weight", "Engineered with a vehicle-specific design for a custom fit", "Concealed main body for OE look and seamless integration with the vehicle", "Tested for safety in accordance with SAE J684", "Precisely welded for superior strength and fit", "Protected by a durable high-gloss black powder coat finish"]', '["Trailer hitch weight ratings are limited to vehicle manufacturer''s stated capacities", "Not compatible for use with vertical hanging bicycles (bike racks that require the bicycles to be hung / mounted vertically)", "Includes installation hardware"]', 'https://www.curtmfg.com/media/catalog/product/1/3/13638_1024x768_a.jpg', false, NULL, 0),
  ('56349', 'wiring', 'Custom wiring harness, 4-way flat output, select toyota tacoma', 105.95, NULL, NULL, '{"Finish": "N/A", "Drilling required": "No"}', '["Plugs into vehicle tail light assembly to provide a 4-way flat socket", "Simple plug-and-play design eliminates the need for cutting or splicing", "4-way flat output connects tail lights, brake lights and turn signals", "Equipped with tail light converter for vehicle-trailer compatibility", "Constructed with SMT circuitry for better performance and durability", "Dust cover included to keep connector clean when not in use"]', '["Vehicle battery connection required", "Includes fuse holder, battery connection wiring and other necessary wiring components"]', 'https://www.curtmfg.com/media/catalog/product/5/6/56349_1024x768_a.jpg', false, NULL, 0),
  ('51455', 'brake_harness', 'Trailer brake controller harness, select toyota tacoma, tundra', 16.95, NULL, NULL, '{"Finish": "N/A", "Drilling required": "No"}', '["Allows a CURT trailer brake controller to be plugged into OEM socket", "Quick plug harness installs with plug-and-play convenience", "Wire colors match standard brake controller harnesses", "Includes 24\" of 12 gauge wire for flexible installation", "Slit-loom sleeve keeps wires contained and protected"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/1/51455_1024x768_a.jpg', false, NULL, 0),
  ('13193', 'hitch', 'Class 3 trailer hitch, 2" receiver, select ford transit 150, 250, 350, e-transit', 285.95, '3', '2"', '{"Gross trailer weight": "6,000 LB", "Tongue weight": "900 LB", "Weight distribution": "8,000 LB", "Receiver": "2 IN", "Finish": "Gloss Black Powder Coat", "Drilling required": "No"}', '["Rated to 6,000 lbs. gross trailer weight and 900 lbs. tongue weight", "Compatible with weight distribution hitch (8,000 lbs. WD / 900 lbs. WDTW)", "Engineered with a vehicle-specific design for a custom fit", "Tested for safety in accordance with SAE J684", "Precisely welded for superior strength and fit", "Protected by a durable high-gloss black powder coat finish"]', '["Trailer hitch weight ratings are limited to vehicle manufacturer''s stated capacities", "Not compatible for use with vertical hanging bicycles (bike racks that require the bicycles to be hung / mounted vertically)", "Includes installation hardware"]', 'https://www.curtmfg.com/media/catalog/product/1/3/13193_1024x768_a.jpg', false, NULL, 0),
  ('14012', 'hitch', 'Class 4 trailer hitch, 2" receiver, select ford transit-150, 250, 350', 332.95, '4', '2"', '{"Gross trailer weight": "8,000 LB", "Tongue weight": "800 LB", "Weight distribution": "10,000 LB", "Receiver": "2 IN", "Finish": "Gloss Black Powder Coat", "Drilling required": "No"}', '["Rated to 8,000 lbs. gross trailer weight and 800 lbs. tongue weight", "Compatible with weight distribution hitch (10,000 lbs. WD / 1,000 lbs. WDTW)", "Engineered with a vehicle-specific design for a custom fit", "Concealed main body for OE look and seamless integration with the vehicle", "Tested for safety in accordance with SAE J684", "Precisely welded for superior strength and fit"]', '["Trailer hitch weight ratings are limited to vehicle manufacturer''s stated capacities", "Includes installation hardware"]', 'https://www.curtmfg.com/media/catalog/product/1/4/14012_1024x768_a.jpg', false, NULL, 0),
  ('56327', 'wiring', 'Custom wiring harness, 4-way flat output, select ford transit-150, 250, 350, hd', 100.95, NULL, NULL, '{"Finish": "N/A", "Drilling required": "No"}', '["Plugs into vehicle tail light assembly to provide a 4-way flat socket Simple plug-and-play design eliminates the need for cutting or splicing 4-way flat output connects tail lights, brake lights and turn signals Equipped with tail light converter for vehicle-trailer compatibility Constructed with SMT circuitry for better performance and durability Dust cover included to keep connector clean when not in use Backed by a limited one-year warranty"]', '["Vehicle battery connection required", "Includes fuse holder, battery connection wiring and other necessary wiring components"]', 'https://www.curtmfg.com/media/catalog/product/5/6/56327_1024x768_a.jpg', false, NULL, 0),
  ('56548', 'wiring', 'Custom wiring harness, 4-way flat output, select ford transit 350, 350 hd dually', 105.95, NULL, NULL, '{"Drilling required": "No"}', '["Plugs into vehicle tail light assembly to provide a 4-way flat socket", "Simple plug-and-play design eliminates the need for cutting or splicing", "4-way flat output connects tail lights, brake lights and turn signals", "Equipped with tail light converter for vehicle-trailer compatibility", "Constructed with SMT circuitry for better performance and durability", "Dust cover included to keep connector clean when not in use"]', '["Vehicle battery connection required", "Includes fuse holder, battery connection wiring and other necessary wiring components"]', 'https://www.curtmfg.com/media/catalog/product/5/6/56548_1024x768_a.jpg', false, NULL, 0),
  ('12123', 'hitch', 'Class 2 trailer hitch, 1-1/4" receiver, select ford transit connect', 286.95, '2', '1-1/4"', '{"Gross trailer weight": "3,500 LB", "Tongue weight": "350 LB", "Weight distribution": "n/a", "Receiver": "1-1/4 IN", "Finish": "Gloss Black Powder Coat", "Drilling required": "No"}', '["Rated to 3,500 lbs. gross trailer weight and 350 lbs. tongue weight", "Engineered with a vehicle-specific design for a custom fit", "Tested for safety in accordance with SAE J684", "Precisely welded for superior strength and fit", "Protected by a durable high-gloss black powder coat finish", "Co-cured in a rust-resistant liquid A-coat, inside and out"]', '["Trailer hitch weight ratings are limited to vehicle manufacturer''s stated capacities", "Not compatible for use with vertical hanging bicycles (bike racks that require the bicycles to be hung / mounted vertically)", "Includes installation hardware"]', 'https://www.curtmfg.com/media/catalog/product/1/2/12123_1024x768_a.jpg', false, NULL, 0),
  ('121233', 'hitch', 'Class 2 trailer hitch, 1-1/4" ball mount, select ford transit connect', 323.95, '2', '1-1/4"', '{"Gross trailer weight": "3,500 LB", "Tongue weight": "350 LB", "Weight distribution": "n/a", "Receiver": "1-1/4 IN", "Finish": "Gloss Black Powder Coat", "Drilling required": "No"}', '["Rated to 3,500 lbs. gross trailer weight and 350 lbs. tongue weight", "Engineered with a vehicle-specific design for a custom fit", "Tested for safety in accordance with SAE J684", "Precisely welded for superior strength and fit", "Protected by a durable high-gloss black powder coat finish", "Co-cured in a rust-resistant liquid A-coat, inside and out"]', '["Trailer hitch weight ratings are limited to vehicle manufacturer''s stated capacities", "Not compatible for use with vertical hanging bicycles (bike racks that require the bicycles to be hung / mounted vertically)", "Includes ball mount #45521, installation hardware, pin & clip", "Trailer ball sold separately"]', 'https://www.curtmfg.com/media/catalog/product/1/2/121233_1024x768_a.jpg', false, NULL, 0),
  ('13167', 'hitch', 'Class 3 trailer hitch, 2" receiver, select ford transit connect', 325.95, '3', '2"', '{"Gross trailer weight": "3,500 LB", "Tongue weight": "525 LB", "Weight distribution": "4,000 LB", "Receiver": "2 IN", "Finish": "Gloss Black Powder Coat", "Drilling required": "No"}', '["Rated to 3,500 lbs. gross trailer weight and 525 lbs. tongue weight", "Compatible with weight distribution hitch (4,000 lbs. WD / 525 lbs. WDTW)", "Engineered with a vehicle-specific design for a custom fit", "Tested for safety in accordance with SAE J684", "Precisely welded for superior strength and fit", "Protected by a durable high-gloss black powder coat finish"]', '["Trailer hitch weight ratings are limited to vehicle manufacturer''s stated capacities", "Not compatible for use with vertical hanging bicycles (bike racks that require the bicycles to be hung / mounted vertically)", "Includes installation hardware"]', 'https://www.curtmfg.com/media/catalog/product/1/3/13167_1024x768_a.jpg', false, NULL, 0),
  ('56218', 'wiring', 'Custom wiring harness, 4-way flat output, select ford transit connect', 96.95, NULL, NULL, '{"Finish": "N/A", "Drilling required": "No"}', '["Plugs into vehicle tail light assembly to provide a 4-way flat socket Simple plug-and-play design eliminates the need for cutting or splicing 4-way flat output connects tail lights, brake lights and turn signals Equipped with tail light converter for vehicle-trailer compatibility Constructed with SMT circuitry for better performance and durability Dust cover included to keep connector clean when not in use Backed by a limited one-year warranty"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/6/56218_1024x768_a.jpg', false, NULL, 0),
  ('55515', 'wiring', 'Replacement OE 4-way flat socket, plugs into factory USCAR plug', 22.95, NULL, NULL, '{"Finish": "N/A", "Drilling required": "No"}', '["Replacement OE 4-Way Flat Socket (Plugs into USCAR) Plugs into USCAR socket to provide 4-way flat trailer wiring connector Simple plug-and-play design eliminates the need for cutting or splicing 4-way flat output connects tail lights, brake lights and turn signals Dust cover included to keep connector clean when not in use Slit loom keeps wires contained and well protected Backed by a limited one-year warranty"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/5/55515_1024x768_a.jpg', true, NULL, 0),
  ('55774', 'factory_adapter', 'Dual-output 7 & 4-way connector, plugs into factory USCAR plug, with bracket', 44.95, NULL, NULL, '{"Finish": "N/A", "Drilling required": "No"}', '["Dual-Output 7 & 4-Way Connector (Plugs into USCAR) Plugs into USCAR socket to provide 4-way and 7-way trailer wiring connectors Fits USCAR-equipped vehicles with factory tow plugs only Simple plug-and-play design eliminates the need for cutting or splicing 4-way flat output connects tail lights, brake lights and turn signals 7-way RV blade socket adds reverse lights, electric brakes and auxiliary power Dust covers included to keep connectors clean when not in use Slit loom keeps wires contained and well protected Metal bracket securely mounts wiring to the vehicle or trailer hitch Backed by a limited one-year warranty"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/5/55774_1024x768_a.jpg', true, NULL, 0),
  ('57672', 'adapter', 'Dual-output adapter, adds 7-way RV blade to 4-way flat, with bracket', 48.95, NULL, NULL, '{}', '["Adapts a 4-way flat socket to fit 4-way flat and 7-way RV blade trailer plugs", "4-way flat output connects tail lights, brake lights and turn signals", "7-way connects tail, brake, reverse, turn signals, brakes and auxiliary power", "Dust covers included to keep connectors clean when not in use", "Slit loom keeps wires contained and well protected", "Metal bracket securely mounts wiring to the vehicle or trailer hitch"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/7/57672_1024x768_a.jpg?width=300&height=300&store=default&image-type=image', false, NULL, 0),
  ('51110', 'brake_controller', 'Venturer time-delay trailer brake controller', 85.95, NULL, NULL, '{}', '["Increases brake power based on gain setting and sensitivity adjustment", "Operates 2-6 trailer brakes at a time (1-3 axles)", "No internal moving parts and no leveling required", "LED indicator lengthens as controller applies power", "Mounts anywhere in the vehicle, at any angle", "Features adjustable power and ramp time"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/1/51110_1024x768_a.jpg?width=300&height=300&store=default&image-type=image', false, 'good', 1),
  ('51146', 'brake_controller', 'TriFlex NEXT proportional trailer brake controller', 156.95, NULL, NULL, '{}', '["Slim, low-profile design for a functional, modern aesthetic", "Unique bracket system for improved dash clearance", "Mounts anywhere in the vehicle, at any angle", "Triple-axis, motion-sensing accelerometer for highly responsive, smooth stops", "Operates 2-8 trailer brakes at a time (1-4 axles)", "Gain and load settings to adapt to various driving conditions"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/1/51146_1024x768_a.jpg?width=300&height=300&store=default&image-type=image', false, 'better', 2),
  ('51170', 'brake_controller', 'Spectrum integrated proportional trailer brake controller', 297.95, NULL, NULL, '{}', '["Controls all brake settings with a simple push-button rotary knob", "Clean, dash-mounted, OEM-style user interface with 10 tri-color LEDs", "Main module can be mounted out of sight", "Triple-axis, motion-sensing accelerometer for highly responsive, smooth stops", "Easily accessible manual override with the press of a button", "Features two installation options: drill mount or surface adhesive mount"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/1/51170_1024x768_a.jpg?width=300&height=300&store=default&image-type=image', false, 'best', 3),
  ('51180', 'brake_controller', 'Echo mobile trailer brake controller, Bluetooth, plugs into 7-way', 319.95, NULL, NULL, '{}', '["Wireless, portable design allows for easy transfer from one vehicle to another", "Bluetooth connection to control all brake settings from your smartphone", "Custom-designed app monitors brake activity and sends status updates", "Zero-tool, plug-and-play install between vehicle-trailer 7-way connectors", "Triple-axis, motion-sensing accelerometer for highly responsive, smooth stops", "Stores multiple vehicle-trailer profiles"]', '[]', 'https://www.curtmfg.com/media/catalog/product/5/1/51180_1024x768_a.jpg?width=300&height=300&store=default&image-type=image', false, 'bluetooth', 4)
